/* AY8910 register/joystick I/O only. All sound is generated by MSX Pico.
 * Maintains the original PSG register masks and reset values.
 * Derived from Marat Fayzullin's fMSX AY8910 register decoder.
 */
#include "AY8910.h"
#include <string.h>
void Reset8910(AY8910 *chip, int clock_hz, int first_channel)
{
    static const uint8_t defaults[16] = {
        0,0,0,0,0,0,0,0xfd,0,0,0,0,0,0,0xff,0
    };
    memset(chip, 0, sizeof *chip);
    memcpy(chip->R, defaults, sizeof defaults);
    chip->Clock = clock_hz / 16;
    chip->First = first_channel;
    chip->Sync = AY8910_ASYNC;
    chip->EPeriod = -1;
}
void WrCtrl8910(AY8910 *chip, uint8_t value)
{
    chip->Latch = value & 15u;
}
void WrData8910(AY8910 *chip, uint8_t value)
{
    Write8910(chip, chip->Latch, value);
}
uint8_t RdData8910(AY8910 *chip)
{
    return chip->R[chip->Latch];
}
void Write8910(AY8910 *chip, uint8_t reg, uint8_t value)
{
    if (reg >= 16) return;
    switch (reg)
    {
    case 1: case 3: case 5: case 13: value &= 0x0f; break;
    case 6: case 8: case 9: case 10: value &= 0x1f; break;
    default: break;
    }
    chip->R[reg] = value;
    if (reg == 13) { chip->EPhase = 0; chip->ECount = 0; }
    chip->Changed = 0;
}
void Sync8910(AY8910 *chip, uint8_t mode)
{
    if (mode != AY8910_FLUSH) chip->Sync = mode;
    chip->Changed = 0;
}
void Loop8910(AY8910 *chip, int elapsed_us)
{
    /* No native sound envelopes: the real Pico PSG generates PCM. */
    (void)chip;
    (void)elapsed_us;
}
